// UDP 发送⽚段   
DatagramSocket socket = new DatagramSocket();   
byte[] data = "hello".getBytes();   
InetAddress addr = InetAddress.getByName("127.0.0.1");   
DatagramPacket packet = new DatagramPacket(data, data.length, addr, 8080);   
